import importlib

modules = [
    "pypdf", "PyPDF2", "reportlab", "pdfplumber", "fitz", "pypdfium2",
    "pdfrw", "borb", "pikepdf",
]
for name in modules:
    try:
        mod = importlib.import_module(name)
        print(f"OK: {name} (version: {getattr(mod, '__version__', 'unknown')})")
    except Exception as exc:
        print(f"MISSING: {name} ({type(exc).__name__}: {exc})")

